// DOMAIN-BUILD-019
export const DOMAIN_BUILD_TREE_SHAKING: KnowledgeNode = {
  id: 'DOMAIN-BUILD-TREE-SHAKING',
  source: 'alg-sys',
  sourceFile: 'KB-04_DOMAIN_PATTERNS.md',
  category: 'domain-specific',
  rule: [
    'TREE-SHAKING: Eliminate unreachable code (dead exports) from the bundle, starting from the entry point.',
    'Tree-shaking requires ESM (static imports) — CommonJS require() is dynamic and defeats static analysis.',
    'Mark files with side effects in package.json ("sideEffects": false) so the bundler knows it can safely drop exports.',
    'Pure function annotations (/*#__PURE__*/) tell the bundler a call has no side effects and can be dropped if unused.',
    'Beware dynamic imports (await import()), conditional requires, and re-exports that create false-live edges.',
    'Verify tree-shaking with a bundle analyzer — flag unexpectedly large bundles that suggest dead code slipped in.',
  ].join('\n'),
  detectionMethod: [
    'CFG: Find packages without a "sideEffects" field (bundler conservatively keeps everything). Flag CommonJS',
    'require() in an ESM-targeted build (defeats tree-shaking). Use a bundle analyzer to detect dead code.',
  ].join(' '),
  fixTemplate: [
    '// package.json — declare no side effects for safe shaking',
    '{ "name": "mylib", "sideEffects": false, "type": "module" }',
    '// Source — mark pure calls so unused ones are dropped',
    'export const createX = /*#__PURE__*/ () => ({ /* ... */ });',
    '// ESM static imports enable static analysis:',
    'import { used } from "mylib";  // unused exports of mylib are dropped',
  ].join('\n'),
  conditions: [
    { field: 'gate', op: 'in', value: ['BUILD', 'VERIFY', 'AUDIT'] },
    { field: 'codePattern', op: 'matches', value: 'treeShak|sideEffects|__PURE__|require\\(' },
  ],
  bulletTemplate: 'No sideEffects declaration, CJS in ESM build, or unmarked pure functions. Enable tree-shaking.',
  warheadTemplate: [
    '# DOMAIN Guidance: Defeated Tree-Shaking',
    '',
    '## What Happened',
    'The build ships dead code because tree-shaking is defeated by missing',
    'sideEffects declarations, CommonJS require, or unmarked impure calls.',
    '',
    '## Why This Matters',
    'Dead code bloats the bundle (slower loads), increases attack surface,',
    'and obscures what is actually used. CommonJS require is dynamic, so the',
    'bundler conservatively keeps everything. Missing pure annotations keep',
    'unused function calls alive.',
    '',
    '## How to Fix',
    'Target ESM with static imports. Set "sideEffects": false where safe.',
    'Annotate pure calls with /*#__PURE__*/. Avoid dynamic imports for',
    'shakeable paths. Verify with a bundle analyzer.',
    '',
    '## Reference',
    'DOMAIN-BUILD-TREE-SHAKING - Dead-code elimination via static analysis',
  ].join('\n'),
  evidenceSpec: { id: 'build-tree-shaking', verify: 'rge-audit', minQuality: 0.90 },
  severity: 'warn',
  layer: 3,
  links: ['DOMAIN-BUILD-ENTRY-POINT', 'DOMAIN-BUILD-MODULE-FORMAT', 'DOMAIN-BUILD-DEPENDENCY-RESOLUTION'],
  selfVerified: true,
};

