    '',
    '## What Happened',
    'API routes use verbs in paths, wrong HTTP methods, or lack versioning.',
    '',
    '## Why This Matters',
    'Verbs in paths (/getOrder) conflict with HTTP method semantics. Wrong',
    'methods (POST for reads) break caching and idempotency. No versioning',
