// DOMAIN-ORCH-047
export const DOMAIN_ORCH_WORKER_POOL: KnowledgeNode = {
  id: 'DOMAIN-ORCH-WORKER-POOL',
  source: 'alg-sys',
  sourceFile: 'KB-04_DOMAIN_PATTERNS.md',
  category: 'domain-specific',
  rule: [
    'WORKER POOL: Process tasks with a bounded pool of concurrent workers, not unbounded concurrency.',
    'Bounded concurrency prevents resource exhaustion (memory, connections, CPU) when tasks pile up.',
    'Size the pool to the bottleneck resource (CPU-bound: pool = cores; IO-bound: pool = connection limit).',
    'Workers are reusable — create once, process many tasks, never spawn a new worker per task (expensive).',
    'On worker error, the worker is recycled (killed + replaced), not reused (it may be in a corrupt state).',
    'Combine with a task queue: the queue feeds the pool; the pool applies bounded concurrency.',
  ].join('\n'),
  detectionMethod: [
    'CFG: Find task processing with unbounded concurrency (Promise.all on all tasks) or per-task worker',
    'creation. Verify pool size matches the bottleneck resource. Check error recycling.',
  ].join(' '),
  fixTemplate: [
    'class WorkerPool<W extends { run(task: T): Promise<void> }> {',
    '  private workers: W[] = [];',
    '  constructor(private size: number, private create: () => W) {',
    '    for (let i = 0; i < size; i++) this.workers.push(create());',
    '  }',
    '  async process(tasks: AsyncIterable<T>): Promise<void> {',
    '    // At most `size` tasks in flight — bounded concurrency',
    '    const semaphore = new Semaphore(this.size);',
    '    for await (const task of tasks) { await semaphore.acquire(); this.run(task).finally(() => semaphore.release()); }',
    '  }',
    '}',
  ].join('\n'),
  conditions: [
    { field: 'gate', op: 'in', value: ['BUILD', 'VERIFY', 'AUDIT'] },
    { field: 'codePattern', op: 'matches', value: 'WorkerPool|workerPool|maxConcurrency|Promise\\.all' },
  ],
  bulletTemplate: 'Unbounded concurrency or per-task workers. Use a bounded reusable pool sized to the bottleneck.',
  warheadTemplate: [
    '# DOMAIN Guidance: Unbounded Concurrency',
    '',
    '## What Happened',
    'Tasks are processed with unbounded concurrency or a new worker per',
    'task.',
    '',
    '## Why This Matters',
    'Unbounded concurrency exhausts resources (memory, connections, CPU)',
    'when tasks pile up. Per-task worker creation is expensive. A corrupt',
    'worker reused after an error stays corrupt. No pool sizing guidance',
    'leads to too-few or too-many workers.',
    '',
    '## How to Fix',
    'Process with a bounded reusable worker pool. Size to the bottleneck',
    'resource (cores for CPU, connections for IO). Recycle workers on',
    'error. Combine with a task queue for backpressure.',
    '',
    '## Reference',
    'DOMAIN-ORCH-WORKER-POOL - Bounded reusable worker pool',
  ].join('\n'),
  evidenceSpec: { id: 'orch-worker-pool', verify: 'rge-audit', minQuality: 0.90 },
  severity: 'warn',
  layer: 3,
  links: ['DOMAIN-ORCH-TASK-QUEUE', 'CONC-WORKER-POOL', 'ARCH-BULKHEAD', 'CONC-RESOURCE-BUDGET'],
  selfVerified: true,
};

