    '',
    '## Why This Matters',
    'A lock without TTL is held forever if the holder crashes (deadlock).',
    'No fencing tokens let a stale holder (whose lock expired but did not',
    'notice) write after another instance acquired the lock (split brain).',
    'Holding locks across long operations risks expiry mid-critical-section.',
    '',
    '## How to Fix',
    'Give every lock a TTL. Use fencing tokens (monotonic counter) so stale',
    'holders cannot write after expiry. Release locks ASAP. Beware clock',
