// DOMAIN-TRADING-062
export const DOMAIN_TRADING_POSITION_MGMT: KnowledgeNode = {
  id: 'DOMAIN-TRADING-POSITION-MGMT',
  source: 'alg-sys',
  sourceFile: 'KB-04_DOMAIN_PATTERNS.md',
  category: 'domain-specific',
  rule: [
    'POSITION MANAGEMENT: Track every open position with entry price, size, direction, and current unrealized PnL in a single source of truth.',
    'A position is reduced by an opposing fill of equal or lesser size; never allow negative position sizes (a buy closing more than short = inverted bug).',
    'Average entry price must be recomputed on partial fills (weighted by size); stale averages produce wrong PnL and wrong stop distances.',
    'Distinguish realized PnL (closed portion) from unrealized PnL (open portion) — mixing them inflates performance reports.',
    'Position state must be persisted and recoverable after a restart; an in-memory-only position book loses everything on crash (P5).',
    'Fees, funding, and commissions are part of the cost basis — a position that ignores fees shows phantom profit.',
  ].join('\n'),
  detectionMethod: [
    'AST: Find position tracking in mutable variables without persistence. Flag closing logic that does not cap at current size.',
    'Verify average entry price is recomputed on partial fills. Check realized vs unrealized PnL separation.',
    'Flag PnL calculations that omit fees/funding/commissions.',
  ].join(' '),
  fixTemplate: [
    'interface Position { symbol: string; side: "long" | "short"; size: number;',
    '  entryPrice: number; feesPaid: number; }',
    '// Close never inverts position — capped at current size',
    'function reduce(pos: Position, qty: number, fillPrice: number): { realized: number; remaining: Position } {',
    '  const closeQty = Math.min(qty, pos.size);  // never negative size',
    '  const pnl = pos.side === "long" ? (fillPrice - pos.entryPrice) * closeQty',
    '                                   : (pos.entryPrice - fillPrice) * closeQty;',
    '  const realized = pnl - fillPrice * closeQty * feeRate;  // fees in basis',
    '  return { realized, remaining: { ...pos, size: pos.size - closeQty } };',
    '}',
  ].join('\n'),
  conditions: [
    { field: 'gate', op: 'in', value: ['BUILD', 'VERIFY', 'AUDIT'] },
    { field: 'codePattern', op: 'matches', value: 'position|entryPrice|unrealized|realized|pnl|PnL' },
  ],
  bulletTemplate: 'Position book in-memory only or closing logic can invert size. Persist, cap closes, separate realized/unrealized PnL.',
  warheadTemplate: [
    '# DOMAIN Guidance: Fragile Position Book',
    '',
    '## What Happened',
    'Positions are tracked in memory without persistence, closing logic',
    'can produce negative sizes, or PnL ignores fees.',
    '',
    '## Why This Matters',
    'An in-memory book is lost on crash (P5) — you reopen blind. A close',
    'exceeding position size inverts direction (long becomes short by',
    'accident). Stale average entries produce wrong stops and PnL. Ignoring',
    'fees inflates reported profit, hiding a losing strategy.',
    '',
    '## How to Fix',
    'Persist every position. Cap closes at current size (never invert).',
    'Recompute average entry on partial fills. Separate realized from',
    'unrealized PnL. Include fees, funding, and commissions in cost basis.',
    '',
    '## Reference',
    'DOMAIN-TRADING-POSITION-MGMT - Single-source persistent position book',
  ].join('\n'),
  evidenceSpec: { id: 'trading-position-mgmt', verify: 'rge-audit', minQuality: 0.90 },
  severity: 'warn',
  layer: 3,
  links: ['DOMAIN-TRADING-ORDER-TYPES', 'DOMAIN-TRADING-RISK-MGMT', 'DOMAIN-TRADING-LEVERAGE', 'DOMAIN-TRADING-STOP-LOSS', 'P5-ATOMIC-STATE'],
  selfVerified: true,
};

