// DOMAIN-TRADING-068
export const DOMAIN_TRADING_ORDER_BOOK: KnowledgeNode = {
  id: 'DOMAIN-TRADING-ORDER-BOOK',
  source: 'alg-sys',
  sourceFile: 'KB-04_DOMAIN_PATTERNS.md',
  category: 'domain-specific',
  rule: [
    'ORDER BOOK: The limit order book (bids/asks with sizes at each price level) is the microstructure source of truth for fills and spread.',
    'Consume the book via a streaming snapshot+diff protocol; never poll the full book repeatedly (P4 — bandwidth and staleness).',
    'Reconstruct the book by applying diffs sequentially; a gap in sequence numbers means a missed update — request a fresh snapshot.',
    'Spread (best ask - best bid) and mid-price ((best ask + best bid)/2) are derived continuously; track them for slippage and signal models.',
    'Book imbalance (bid size vs ask size at top levels) is a short-term directional signal — but spoofing (fake large orders) distorts it.',
    'The book is high-frequency; debounce or aggregate updates before feeding signal logic to avoid thrashing on every tick.',
  ].join('\n'),
  detectionMethod: [
    'AST: Find order-book polling via REST (full snapshot each time) instead of websocket diffs. Flag book reconstruction without sequence validation.',
    'Verify spread/mid computation. Check for high-frequency tick handling without debouncing.',
  ].join(' '),
  fixTemplate: [
    '// Snapshot + diff protocol with sequence validation',
    'let book: PriceLevel[] = []; let lastSeq = 0;',
    'ws.on("message", (msg) => {',
    '  if (msg.type === "snapshot") { book = msg.levels; lastSeq = msg.seq; }',
    '  else if (msg.type === "diff") {',
    '    if (msg.seq !== lastSeq + 1) { requestSnapshot(); return; } // gap -> resync',
    '    lastSeq = msg.seq;',
    '    book = applyDiff(book, msg.changes);',
    '  }',
    '});',
    '// Derived metrics',
    'const spread = book.bestAsk - book.bestBid;',
    'const imbalance = book.bidSizeTop5 / (book.bidSizeTop5 + book.askSizeTop5);',
  ].join('\n'),
  conditions: [
    { field: 'gate', op: 'in', value: ['BUILD', 'VERIFY', 'AUDIT'] },
    { field: 'codePattern', op: 'matches', value: 'orderBook|bidAsk|spread|midPrice|imbalance|depth|level2' },
  ],
  bulletTemplate: 'Book polled via REST or reconstructed without sequence checks. Stream diffs, validate sequence, derive spread/mid.',
  warheadTemplate: [
    '# DOMAIN Guidance: Fragile Order-Book Handling',
    '',
    '## What Happened',
    'The order book is polled via repeated full snapshots, or diffs are',
    'applied without sequence validation.',
    '',
    '## Why This Matters',
    'REST polling wastes bandwidth and serves stale books (P4). Applying',
    'diffs with a sequence gap corrupts the book — fills and signals use',
    'wrong prices. Missing spread/mid derivation means slippage and',
    'imbalance signals are unavailable. Processing every tick thrashes',
    'signal logic.',
    '',
    '## How to Fix',
    'Stream snapshot+diff over websocket. Validate sequence numbers —',
    'resync on gap. Derive spread and mid continuously. Track imbalance',
    'with spoofing awareness. Debounce/aggregate before signal logic.',
    '',
    '## Reference',
    'DOMAIN-TRADING-ORDER-BOOK - Sequence-validated streaming book',
  ].join('\n'),
  evidenceSpec: { id: 'trading-order-book', verify: 'rge-audit', minQuality: 0.90 },
  severity: 'warn',
  layer: 3,
  links: ['DOMAIN-TRADING-LIQUIDITY', 'DOMAIN-TRADING-SLIPPAGE', 'DOMAIN-TRADING-EXECUTION-ALGO', 'DOMAIN-TRADING-CANDLESTICK'],
  selfVerified: true,
};

// DOMAIN-TRADING-069
export const DOMAIN_TRADING_CANDLESTICK: KnowledgeNode = {
  id: 'DOMAIN-TRADING-CANDLESTICK',
  source: 'alg-sys',
  sourceFile: 'KB-04_DOMAIN_PATTERNS.md',
  category: 'domain-specific',
  rule: [
    'CANDLESTICK (OHLCV): Candles aggregate ticks into OHLCV bars per timeframe — they are a lossy summary, not the raw market.',
    'Build candles by bucketing trades by timestamp into fixed intervals (1m, 5m, 1h); a candle is O=first, H=max, L=min, C=last in the bucket.',
    'The current (unclosed) candle is mutable — it updates with each tick until the interval closes; never act on a closed-candle signal from an open candle.',
    'Timeframe must be explicit and consistent; mixing a signal computed on 1m with execution on 1h produces look-ahead or lag bugs.',
    'Gaps (no trades in an interval) produce candles with O=H=L=C=previous close or are omitted — handle both, do not assume continuity.',
    'Volume is cumulative within the bucket; a candle with low volume is unreliable regardless of its OHLC shape.',
  ].join('\n'),
  detectionMethod: [
    'AST: find candle-building code that acts on open (unclosed) candles. Flag signals computed on mismatched timeframes.',
    'Verify gap handling (empty intervals). Check volume-awareness in candle-based signals.',
  ].join(' '),
  fixTemplate: [
    'interface Candle { ts: number; o: number; h: number; l: number; c: number; v: number; closed: boolean; }',
    'function buildCandle(trades: Trade[], interval: number, bucketStart: number): Candle {',
    '  const inBucket = trades.filter(t => t.ts >= bucketStart && t.ts < bucketStart + interval);',
    '  if (inBucket.length === 0) return { ts: bucketStart, o: 0, h: 0, l: 0, c: 0, v: 0, closed: false }; // gap',
    '  const prices = inBucket.map(t => t.price);',
    '  return {',
    '    ts: bucketStart,',
    '    o: prices[0], h: Math.max(...prices), l: Math.min(...prices), c: prices.at(-1)!,',
    '    v: inBucket.reduce((s, t) => s + t.qty, 0),',
    '    closed: Date.now() >= bucketStart + interval, // closed only after interval elapsed',
    '  };',
    '}',
    '// Never act on signal from an open candle',
    'if (!candle.closed) return; // wait for close',
  ].join('\n'),
  conditions: [
    { field: 'gate', op: 'in', value: ['BUILD', 'VERIFY', 'AUDIT'] },
    { field: 'codePattern', op: 'matches', value: 'candle|OHLC|ohlcv|timeframe|kline|candlestick' },
  ],
  bulletTemplate: 'Signals act on open candles or timeframe mismatch. Build OHLCV correctly, gate signals on candle close, handle gaps.',
  warheadTemplate: [
    '# DOMAIN Guidance: Improper Candlestick Use',
    '',
    '## What Happened',
    'Signals are evaluated on open (unclosed) candles, or timeframes are',
    'mixed between signal and execution.',
    '',
    '## Why This Matters',
    'An open candle changes every tick — a signal from it flickers and',
    'repaints (looks different in hindsight). Mismatched timeframes cause',
    'look-ahead (using future data) or lag (acting late). Unhandled gaps',
    'produce phantom candles. Low-volume candles give false patterns.',
    '',
    '## How to Fix',
    'Bucket trades into OHLCV by interval. Gate signals on candle close',
    'only. Keep timeframe consistent across signal and execution. Handle',
    'gaps explicitly. Weight signal confidence by candle volume.',
    '',
    '## Reference',
    'DOMAIN-TRADING-CANDLESTICK - Lossy OHLCV aggregation with close-gating',
  ].join('\n'),
  evidenceSpec: { id: 'trading-candlestick', verify: 'rge-audit', minQuality: 0.90 },
  severity: 'warn',
  layer: 3,
  links: ['DOMAIN-TRADING-INDICATORS', 'DOMAIN-TRADING-ORDER-BOOK', 'DOMAIN-TRADING-BACKTEST', 'DOMAIN-TRADING-LIQUIDITY'],
  selfVerified: true,
};

