    'async function vwap(parent: Order, deadline: number): Promise<void> {',
    '  const slices = computeVwapSchedule(parent.qty, volumeProfile);',
    '  for (const slice of slices) {',
    '    if (Date.now() > deadline) {',
    '      await marketRemaining(parent); // fallback — ensure completion',
    '      return;',
    '    }',
    '    const childQty = Math.min(slice.qty, maxParticipateRate * recentVolume);',
    '    const fill = await placeChild(parent.symbol, parent.side, childQty, slice.passive ? "limit" : "market");',
    '    parent.qty -= fill.qty;',
