    'HMR replaces modules without cleaning up old side effects, or HMR',
    'runtime leaks into production.',
    '',
    '## Why This Matters',
    'No cleanup leaks listeners/timers that double-fire on each HMR cycle.',
    'Blind state replacement loses app state (the opposite of HMR goal).',
    'HMR in production ships dead dev code. A silent HMR failure serves a',
    'stale module, misleading the developer. Missing accept-boundary means',
