// DOMAIN-BUILD-090
export const DOMAIN_BUILD_SERVER_SIDE_RENDER: KnowledgeNode = {
  id: 'DOMAIN-BUILD-SERVER-SIDE-RENDER',
  source: 'alg-sys',
  sourceFile: 'KB-04_DOMAIN_PATTERNS.md',
  category: 'domain-specific',
  rule: [
    'SERVER-SIDE RENDER (SSR): SSR renders the initial HTML on the server so users see content before JS hydrates — faster first paint, better SEO.',
    'SSR rendering must be pure and side-effect-free per request (no module-level mutable state) — shared state between requests causes cross-user data leaks.',
    'Components must be isomorphic (run on both server and client) — guard browser-only APIs (window, document) behind typeof checks or useEffect.',
    'Hydration: the client attaches event listeners to server-rendered HTML; mismatched server/client output produces hydration errors and re-render.',
    'Data fetching for SSR must happen before render (per-route data loaders); do not fetch in component-mount on the server (no effect runs).',
    'Streaming SSR (render to stream) sends HTML as it is ready, improving TTFB for large pages — but requires careful suspense/stream boundaries.',
  ].join('\n'),
  detectionMethod: [
    'AST: Find module-level mutable state accessed during render (cross-request leak). Flag browser-only API use without typeof/effect guards.',
    'Verify hydration consistency (server/client output match). Check data fetching is pre-render, not in mount effects.',
  ].join(' '),
  fixTemplate: [
    '// Isomorphic component — guard browser APIs',
    'function useWindowSize() {',
    '  const [size, setSize] = useState({ w: 0, h: 0 });',
    '  useEffect(() => { // effect runs client-only, not on server',
    '    const onResize = () => setSize({ w: window.innerWidth, h: window.innerHeight });',
    '    window.addEventListener("resize", onResize); onResize();',
    '    return () => window.removeEventListener("resize", onResize);',
    '  }, []);',
    '  return size;',
    '}',
    '// Pre-render data fetch (not in mount effect)',
    'export async function loader() { return await fetchInitialData(); }',
  ].join('\n'),
  conditions: [
    { field: 'gate', op: 'in', value: ['BUILD', 'VERIFY', 'AUDIT'] },
    { field: 'codePattern', op: 'matches', value: 'renderToString|hydrate|SSR|serverSide|isomorphic|useEffect|loader' },
  ],
  bulletTemplate: 'SSR with module-level mutable state or unguarded browser APIs. Keep render pure, guard browser APIs, match hydration, fetch pre-render.',
  warheadTemplate: [
    '# DOMAIN Guidance: Impure or Non-Isomorphic SSR',
    '',
    '## What Happened',
    'SSR uses module-level mutable state, or browser-only APIs are called',
    'without guards, or data is fetched in mount effects.',
    '',
    '## Why This Matters',
    'Module-level state shared across requests leaks data between users',
    '(security/correctness). Unguarded window/document throws on the server.',
    'Server/client output mismatch causes hydration errors and re-render.',
    'Fetching in mount effects means the server renders empty (no effect',
    'runs) — SSR gives no SEO/first-paint benefit.',
    '',
    '## How to Fix',
    'Keep SSR render pure (per-request state). Make components isomorphic',
    '(guard browser APIs with typeof/useEffect). Ensure hydration',
    'consistency. Fetch data in pre-render loaders, not mount effects.',
    'Consider streaming SSR for TTFB.',
    '',
    '## Reference',
    'DOMAIN-BUILD-SERVER-SIDE-RENDER - Pure isomorphic SSR with hydration',
  ].join('\n'),
  evidenceSpec: { id: 'build-ssr', verify: 'rge-audit', minQuality: 0.90 },
  severity: 'warn',
  layer: 3,
  links: ['DOMAIN-BUILD-STATIC-GEN', 'DOMAIN-BUILD-LAZY-LOADING', 'DOMAIN-BUILD-CODE-SPLITTING', 'DOMAIN-BUILD-ENTRY-POINT'],
  selfVerified: true,
};

