  conditions: [{ field: 'gate', op: 'in', value: ['BUILD', 'AUDIT'] }, { field: 'codePattern', op: 'matches', value: 'health|liveness|readiness|healthz' }],
  bulletTemplate: 'Separate liveness (alive) and readiness (can-serve) endpoints.',
